/**
 * One of the learner's folders over their deck. A label, never a second
 * deck — see `GET /me/card-groups`.
 */
export interface CardGroup {
  id: string;
  name: string;
  /**
     * How many cards are in it. Sent because these render as filter chips
     * and a chip showing a number has to show the number a tap would
     * produce — the argument the wordbook's filters make by name.
     */
  cardCount: number;
  /**
     * How many of them are still Mới or Đang học — the cards a session
     * over this folder would draw from (R-15's danh sách ôn hằng ngày).
     *
     * `cardCount` alone cannot answer the question a "review this folder"
     * control has to answer: a folder of forty-eight cards all marked Đã
     * nhớ offers nothing, and a link into it would be a tap that wasted
     * itself.
     *
     * A list length, not a score. It falls only because the learner said a
     * card was known; nothing computes it and no date moves it.
     */
  reviewableCount: number;
  createdAt: string;
}
